import * as THREE from 'three'
import { Chunks } from './meshbuilder'
import { Colliders } from './colliders'
import { BAY_W, FLOOR_H, type Kind, type Mats } from './materials'
import { LANDMARKS } from './landmarks'
import type { AvenueData } from './avenue/types'

type Pt = number[]
/** Street furniture of проспект Свободи, generated by scripts/layout-avenue.ts. */
export interface Street extends Partial<AvenueData> {
  trees: number[][]   // [x, z, seed, kind] kind 0 chestnut, 1 maple (plaza), 2 linden
  benches: number[][] // [x, z, yaw, kind] kind 0 park, 1 long plaza, 2 arc around the monument
  lamps: number[][]   // [x, z, yaw]
  fountain: { x: number; z: number; yaw: number; len: number; wid: number }
  chess: number[][]   // [x, z, yaw] tables
  drinking: { x: number; z: number }
  beds: { x: number; z: number; r0: number; r1: number; ang: number; span: number }[]
  ribbons: { kind: string; l: number[][]; r: number[][] }[]
  plaza: number[][]
  monument: { x: number; z: number; yaw: number; stele: { x: number; z: number }; steleYaw: number }
}
export interface CityData {
  spawn: { x: number; z: number; yaw: number }
  buildings: { id: string; r: Pt[][]; h: number; lv: number; t: string; sd?: number; rs?: string; bc?: string }[] // sd = OSM start_date year, rs = roof:shape, bc = building:colour
  roads: { p: Pt[]; k: string; s: string; w: number }[]
  street?: Street
}

// muted, slightly dirty stucco tones typical for Lviv's Austro-Hungarian centre
const PALETTE = [0xd2bf8c, 0xd9cdb2, 0xaeb7a0, 0xc2a090, 0xb7b3a8, 0x9aa6ac, 0xa88f78, 0xcdb48a].map((h) => new THREE.Color(h))
const hash = (s: string) => { let h = 2166136261; for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619); return h >>> 0 }
const area = (r: Pt[]) => r.reduce((a, p, i) => a + (p[0] * r[(i + 1) % r.length][1] - r[(i + 1) % r.length][0] * p[1]), 0) / 2
const LAYER: Record<string, number> = { pedestrian: 1, footway: 2, steps: 2, path: 2, cycleway: 2, platform: 2 }

export function buildCity(data: CityData, mats: Mats, opts: { shadows: boolean }) {
  const group = new THREE.Group()
  const colliders = new Colliders()
  // chunk size = culling granularity vs draw calls (each chunk costs ~3 draws for buildings); see docs/performance.md
  const buildings = new Chunks(400), roads = new Chunks(Infinity) // roads: ~5k triangles in total, a single chunk (1 draw per material) beats culling
  let minX = 1e9, maxX = -1e9, minZ = 1e9, maxZ = -1e9

  for (const b of data.buildings) {
    try {
      const hs = hash(b.id)
      // OSM walls: outer ring must have area > 0, holes < 0 (see wall normal below)
      const rings = b.r.map((r, i) => (area(r) > 0) === (i === 0) ? r : [...r].reverse())
      const A = Math.abs(area(b.r[0]))
      const lm = LANDMARKS[b.id]
      const h = lm?.h ?? (b.h || (A < 80 ? 3.5 : 4 * FLOOR_H + ((hs % 7) - 3) * 0.5))
      const floors = lm?.floors ?? Math.max(1, Math.round(h / FLOOR_H))
      const tint = lm?.tint !== undefined ? new THREE.Color(lm.tint) : b.bc ? new THREE.Color(b.bc).lerp(new THREE.Color(0xffffff), 0.2) : PALETTE[hs % PALETTE.length]
      const cx = rings[0][0][0], cz = rings[0][0][1]
      // facade style from the OSM construction year: pre-1830 and post-1945 buildings are plain (small windows), the historicist era gets pilasters/arches
      const st = lm?.style ?? (b.sd && (b.sd < 1830 || b.sd > 1945) ? 2 : b.sd ? (hs >>> 3) % 2 : (hs >>> 3) % 3), fh = h / floors
      // storeys: rusticated ground floor, plain middle storeys, top storey with cornice
      // all sections go into ONE mesh per chunk; the facade tile is a per-vertex layer of mats.facade's texture array
      const fb = buildings.batch(cx, cz, mats.facade), L = (k: Kind) => mats.facadeLayer(k, st)
      const gH = lm?.groundH // photo-facade buildings (avenue/facades.ts): shop level of gH metres, the photo panel covers everything above it
      const sections = gH !== undefined
        ? [...(gH > 0 ? [{ y0: 0, y1: Math.min(gH, 4.8), v: 1, tile: L('ground') }] : []), ...(gH > 4.8 ? [{ y0: 4.8, y1: gH, v: (gH - 4.8) / FLOOR_H, tile: L('mid') }] : []), { y0: gH, y1: h, v: (h - gH) / FLOOR_H, tile: L('mid') }]
        : floors === 1
        ? [{ y0: 0, y1: h, v: h / FLOOR_H, tile: L('ground') }]
        : [{ y0: 0, y1: fh, v: 1, tile: L('ground') },
           ...(floors > 2 ? [{ y0: fh, y1: h - fh, v: floors - 2, tile: L('mid') }] : []),
           { y0: h - fh, y1: h, v: 1, tile: L('top') }]
      for (const ring of rings) for (let i = 0; i < ring.length; i++) {
        const [ax, az] = ring[i], [bx, bz] = ring[(i + 1) % ring.length]
        const dx = bx - ax, dz = bz - az, len = Math.hypot(dx, dz)
        if (len < 0.05) continue
        colliders.add(ax, az, bx, bz, h)
        minX = Math.min(minX, ax); maxX = Math.max(maxX, ax); minZ = Math.min(minZ, az); maxZ = Math.max(maxZ, az)
        const nx = dz / len, nz = -dx / len, u = Math.max(1, Math.round(len / BAY_W))
        if (!lm?.skipMesh) for (const { y0, y1, v, tile } of sections) {
          const V = (x: number, y: number, z: number, uu: number, vv: number) => fb.add(x, y, z, nx, 0, nz, uu, vv, tint, tile)
          // CCW seen from outside: (b0, a0, a1), (b0, a1, b1)
          const b0 = V(bx, y0, bz, u, 0), a0 = V(ax, y0, az, 0, 0), a1 = V(ax, y1, az, 0, v), b1 = V(bx, y1, bz, u, v)
          fb.tri(b0, a0, a1); fb.tri(b0, a1, b1)
        }
      }
      // roof (flat; roof:shape is out of scope)
      const flat = rings.flat()
      const faces = THREE.ShapeUtils.triangulateShape(
        rings[0].map((p) => new THREE.Vector2(p[0], p[1])),
        rings.slice(1).map((r) => r.map((p) => new THREE.Vector2(p[0], p[1]))),
      )
      const roof = buildings.batch(cx, cz, mats.roofs[lm?.roof ?? (hs >>> 7) % mats.roofs.length])
      if (!lm?.skipMesh) {
        const vi = flat.map((p) => roof.add(p[0], h, p[1], 0, 1, 0, p[0], p[1])) // ring vertices shared by all roof triangles
        for (const [i, j, k] of faces) {
          const [p, q, r] = [flat[i], flat[j], flat[k]]
          const up = (q[1] - p[1]) * (r[0] - p[0]) - (q[0] - p[0]) * (r[1] - p[1]) >= 0
          if (up) roof.tri(vi[i], vi[j], vi[k]); else roof.tri(vi[i], vi[k], vi[j])
        }
      }
      colliders.addBuilding(rings, h)
      lm?.model?.(rings[0], { group, shadows: opts.shadows })
    } catch (e) {
      console.warn('skip building', b.id, e) // bad OSM polygon: drop it, don't kill the load
    }
  }

  for (const r of data.roads) {
    const layer = LAYER[r.k] ?? 0, mat = mats.road(r.k === 'cycleway' ? 'cycleway' : r.s, layer), p = r.p, hw = r.w / 2
    // per-vertex left offset, averaged between adjacent segments (miter clamped)
    const off = p.map((_, i) => {
      const a = p[Math.max(0, i - 1)], b = p[Math.min(p.length - 1, i + 1)]
      const dx = b[0] - a[0], dz = b[1] - a[1], l = Math.hypot(dx, dz) || 1
      return [(-dz / l) * hw, (dx / l) * hw]
    })
    for (let i = 0; i < p.length - 1; i++) {
      const bt = roads.batch(p[i][0], p[i][1], mat)
      const L0 = [p[i][0] + off[i][0], p[i][1] + off[i][1]], R0 = [p[i][0] - off[i][0], p[i][1] - off[i][1]]
      const L1 = [p[i + 1][0] + off[i + 1][0], p[i + 1][1] + off[i + 1][1]], R1 = [p[i + 1][0] - off[i + 1][0], p[i + 1][1] - off[i + 1][1]]
      // triangles wound to face up
      const [l0, l1, r0, r1] = [L0, L1, R0, R1].map((q) => bt.add(q[0], 0, q[1], 0, 1, 0, q[0], q[1]))
      bt.tri(l0, l1, r0); bt.tri(r0, l1, r1)
    }
  }

  buildings.build(group, { cast: opts.shadows, receive: opts.shadows })
  roads.build(group, { receive: opts.shadows })
  return { group, colliders, bounds: { minX: minX - 30, maxX: maxX + 30, minZ: minZ - 30, maxZ: maxZ + 30 } }
}
